import {Popover, Button} from '@heroui/react';

function CustomPopover() {
  return (
    <Popover>
      <Button>Open</Button>
      <Popover.Content className="bg-accent text-accent-foreground">
        <Popover.Dialog>
          <Popover.Heading>Custom Styled</Popover.Heading>
          <p>This popover has custom styling</p>
        </Popover.Dialog>
      </Popover.Content>
    </Popover>
  );
}

import {Separator} from '@heroui/react';

function CustomSeparator() {
  return (
    <Separator className="my-8 bg-gradient-to-r from-transparent via-default-500 to-transparent" />
  );
}

import { Skeleton } from '@heroui/react';

function CustomSkeleton() {
  return (
    <Skeleton className="h-20 w-32 rounded-full" />
  );
}

import {Spinner} from '@heroui/react';

function CustomSpinner() {
  return (
    <Spinner className="text-blue-500" />
  );
}

import { Switch, Label } from '@heroui/react';

function CustomSwitch() {
  return (
    <Switch>
      {({isSelected}) => (
        <>
          <Switch.Control
            className="h-6 w-9 bg-gray-300 data-[selected=true]:bg-green-500"
            data-selected={isSelected}
          >
            <Switch.Thumb className="bg-white" />
          </Switch.Control>
          <Label>Custom styled switch</Label>
        </>
      )}
    </Switch>
  );
}

import { TextField } from '@heroui/react';

function CustomTextField() {
  return (
    <TextField className="space-y-3">
      <TextField.Label className="text-lg font-bold">
        Custom styled field
      </TextField.Label>
      <TextField.Input
        className="border-2 border-blue-500 focus:border-blue-600"
        placeholder="Custom input"
      />
      <TextField.Description className="text-xs italic">
        With custom styles
      </TextField.Description>
    </TextField>
  );
}

import {Tooltip, Button} from '@heroui/react';

function CustomTooltip() {
  return (
    <Tooltip>
      <Button>Hover me</Button>
      <Tooltip.Content className="bg-accent text-accent-foreground">
        <p>Custom styled tooltip</p>
      </Tooltip.Content>
    </Tooltip>
  );
}
